	x := "5.0"
	tt = decimalTester(t, &x, "", "10.0", "0.5")
	retype(tt, "10.5")
	if n := amount(t, tt); x != "5.0" || n.Description != "Enter 10.0 or less" {
		t.Errorf("above the top: %q, %+v", x, n)
	}
	retype(tt, "-1000000000.5")
	if x != "-1000000000.5" {
		t.Errorf("no bottom: %q", x)
	}
