		scale int
		want  string // the units, "" for a fault
		fault decimalFault
	}{
		{"0", 2, "0", decimalFine},
		{"1.", 2, "100", decimalFine},
		{".5", 2, "50", decimalFine},
		{"-0.00", 2, "0", decimalFine},
		{"123,456.7", 1, "1234567", decimalFine},
		{"1.230000", 2, "123", decimalFine},
		{"1.231", 2, "", decimalTooExact},
		{"1.5", 0, "", decimalTooExact},
		{"", 2, "", decimalInvalid},
		{".", 2, "", decimalInvalid},
		{"-.", 2, "", decimalInvalid},
