package ui

import (
	"fmt"
	"image"
	"testing"
	"time"
)

// cacheCard is a card with a shadow, text, a gradient and a child beyond
// its box, with a drawing moving next to it, kept by Cache when cached; tilt
// rotates it, wide widens it, and accent colors its text.
type cacheCard struct {
	cached     bool
	tilt, wide float32
	accent     Color
	st         *state
	moves      int
}

func (v *cacheCard) view(c *context) {
	coreColumn(c).Fill().Background(RGB(255, 255, 255)).Padding(20).Children(func() {
		// Text over the card's opaque background, smoothed as over the
		// window's (ClearType's subpixels on Windows), in its bitmap too.
		card := coreBox(c).Width(120+v.wide).Height(50).Radius(12).Background(RGB(30, 60, 200)).
			Shadow(0, 4, 10, 2, RGBA(0, 0, 0, 90)).Padding(8).Children(func() {
			coreText(c, "Daily mix").TextColor(v.accent)
			coreBox(c).Absolute().Right(0).Top(0).Size(30, 50).Radius(12).Gradient(RGB(30, 60, 200), RGB(200, 40, 120), 30)
			// Beyond the card, which does not clip it.
			coreBox(c).Absolute().Left(150+v.wide).Top(30).Size(30, 14).Background(RGB(20, 160, 60))
		})
		if v.tilt != 0 {
			card.Rotate(v.tilt)
		}
		if v.cached {
			card.Cache()
		}
		v.st = card.st
		coreBox(c).Size(60, 12).Draw(func(p *Painter, r Rect) {
			v.moves++
			p.AnimationFrame()
			p.Fill(Rect{r.X + float32(p.Now().UnixMilli()%50), r.Y, 8, r.H}, RGB(0, 0, 0), 2)
		})
	})
}

// sameImage reports where a and b differ by more than a level or two of a
// channel, as compositing a layer rounds twice: "" for nowhere.
func sameImage(a, b *image.RGBA) string {
	n, at := 0, ""
	for i := range a.Pix {
		d := int(a.Pix[i]) - int(b.Pix[i])
		if d < -2 || d > 2 {
			if n++; at == "" {
				px := i / 4
				at = fmt.Sprintf("(%d,%d) %d≠%d", px%a.Rect.Dx(), px/a.Rect.Dx(), a.Pix[i], b.Pix[i])
			}
		}
	}
	if n == 0 {
		return ""
	}
	return fmt.Sprintf("%d bytes differ, first at %s", n, at)
}

// TestCacheKeepsLayer: a card kept by Cache shows as it does painted as
// it is, beyond its box too, and its bitmap is drawn once while a drawing
// next to it moves, whether frames paint the window whole or only the
// drawing; then once again as its text changes color, its size changes,
// or the window's scale does, but not as it turns.
func TestCacheKeepsLayer(t *testing.T) {
	for _, parts := range []bool{true, false} {
		t.Run(fmt.Sprint("parts=", parts), func(t *testing.T) {
			cached := &cacheCard{cached: true, accent: RGB(255, 255, 255)}
			plain := &cacheCard{accent: RGB(255, 255, 255)}
			ct, pt := newRepaintTester(cached.view), newRepaintTester(plain.view)
			ct.rt.noParts, pt.rt.noParts = !parts, !parts
			if cached.st.effectLayer == nil || cached.st.effectLayer.img.Transient {
				t.Fatalf("layer %v, want one kept", cached.st.effectLayer)
			}
			layer := cached.st.effectLayer.img
			// check draws frames as the drawing moves, from the frame in
			// which the layer had version v: drawn again in the first, as
			// redrawn says, then not.
			check := func(what string, v uint64, redrawn, resampled bool) {
				t.Helper()
				for i := range 4 {
					if i > 0 {
						ct.frame(7 * time.Millisecond)
						pt.frame(7 * time.Millisecond)
					}
					if d := sameImage(ct.Image(), pt.Image()); d != "" && !resampled {
						t.Fatalf("%s, frame %d: cached differs from painted as it is: %s", what, i, d)
					}
					if i == 0 && redrawn != (layer.Version() != v) {
						t.Errorf("%s: layer drawn again %v, want %v", what, layer.Version() != v, redrawn)
					}
					if i > 0 && layer.Version() != v {
						t.Errorf("%s, frame %d: layer drawn again while nothing changed", what, i)
					}
					v = layer.Version()
				}
			}
			check("moving next to it", layer.Version(), false, false)
			for _, step := range []struct {
				what    string
				change  func(v *cacheCard)
				redrawn bool
			}{
				{"text colored", func(v *cacheCard) { v.accent = RGB(255, 220, 0) }, true},
				{"widened", func(v *cacheCard) { v.wide = 40 }, true},
				{"turned", func(v *cacheCard) { v.tilt = 10 }, false},
			} {
				v := layer.Version()
				step.change(cached)
				step.change(plain)
				ct.Frame()
				pt.Frame()
				// Turned, the bitmap is resampled, where painting turns
				// the shapes themselves.
				check(step.what, v, step.redrawn, step.what == "turned")
			}
			cached.tilt, plain.tilt = 0, 0
			ct.Frame()
			pt.Frame()
			v := layer.Version()
			ct.SetScale(2)
			pt.SetScale(2)
			if layer.Version() == v {
				t.Errorf("at another scale: layer not drawn again")
			}
			if d := sameImage(ct.Image(), pt.Image()); d != "" {
				t.Errorf("at scale 2: cached differs from painted as it is: %s", d)
			}
		})
	}
}

// TestCacheAreaClipped: the bitmap of an element that clips is its box
// and its shadows' reach, not what lies inside beyond it.
func TestCacheAreaClipped(t *testing.T) {
	var st *state
	coreNewTester(func(c *context) {
		e := coreBox(c).Size(100, 40).ClipX().ClipY().Cache().Children(func() {
			coreBox(c).Size(400, 300).Background(RGB(255, 0, 0))
		})
		st = e.st
	}, 600, 400)
	w, h := st.effectLayer.Size()
	if w != 128 || h != 64 {
		t.Errorf("layer of %d×%d, want 128×64 for 100×40 and the focus ring's reach", w, h)
	}
}

// TestCacheKeepsBlur: a blurred element kept by Cache renders into its
// bitmap once, while the frames after it paint the window again.
func TestCacheKeepsBlur(t *testing.T) {
	var st *state
	tt := newRepaintTester(func(c *context) {
		coreRow(c).Children(func() {
			st = coreBox(c).Size(60, 30).Background(RGB(200, 0, 0)).Blur(4).Cache().st
			coreBox(c).Size(20, 20).Draw(func(p *Painter, r Rect) {
				p.AnimationFrame()
				p.Fill(Rect{r.X, r.Y, float32(p.Now().UnixMilli() % 20), r.H}, RGB(0, 0, 0), 0)
			})
		})
	})
	tt.rt.noParts = true
	layer := st.effectLayer.img
	v := layer.Version()
	for range 5 {
		tt.frame(9 * time.Millisecond)
	}
	if layer.Transient || layer.Version() != v {
		t.Errorf("transient %v, drawn %d times again, want kept", layer.Transient, layer.Version()-v)
	}
}

package sqlite

import (
	"context"
	"encoding/json"
	"errors"
	"math"
	"path/filepath"
	"reflect"
	"sync"
	"testing"
	"time"

	"github.com/egoist/mygo/internal/wait"
)

func testDB(t *testing.T, path string) *DB {
	t.Helper()
	if testing.Short() {
		t.Skip("requires the plugin's native SQLite library; run go generate ./plugins/sqlite")
	}
	db, err := Open(context.Background(), path, OpenOptions{})
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() {
		if err := db.Close(); err != nil {
			t.Error(err)
		}
	})
	return db
}

func execute(t *testing.T, db *DB, sql string, args ...any) Result {
	t.Helper()
	r, err := db.Execute(context.Background(), sql, args...)
	if err != nil {
		t.Fatal(err)
	}
	return r
}

func query(t *testing.T, db *DB, sql string, args ...any) Rows {
	t.Helper()
	r, err := db.Query(context.Background(), sql, args...)
	if err != nil {
		t.Fatal(err)
	}
	return r
}

func TestValues(t *testing.T) {
	db := testDB(t, ":memory:")
	values := []any{nil, int64(math.MinInt64), int64(math.MaxInt64), -3.125, "中文🙂\x00text", []byte{0, 1, 255}, []byte{}, "", true}
	rows := query(t, db, "SELECT ? AS same, ? AS same, ?, ?, ?, ?, ?, ?, ?", values...)
	want := append([]any{}, values...)
	want[8] = int64(1)
	if !reflect.DeepEqual(rows.Values, [][]any{want}) {
		t.Fatalf("values = %#v, want %#v", rows.Values, want)
	}
	if rows.Columns[0] != "same" || rows.Columns[1] != "same" {
		t.Fatal(rows.Columns)
	}
	execute(t, db, "CREATE TABLE items (id INTEGER PRIMARY KEY, name TEXT UNIQUE, bytes BLOB)")
	r := execute(t, db, "INSERT INTO items(name, bytes) VALUES (?, ?)", "it's a ?; DROP TABLE items; --", []byte{1, 2})
	if r.Changes != 1 || r.LastInsertID != 1 {
		t.Fatal(r)
	}
	if n := execute(t, db, "CREATE TABLE other (n)").Changes; n != 0 {
		t.Fatalf("DDL changes = %d", n)
	}
	got := query(t, db, "SELECT name, bytes FROM items").Values[0]
	if got[0] != "it's a ?; DROP TABLE items; --" || !reflect.DeepEqual(got[1], []byte{1, 2}) {
		t.Fatal(got)
	}
	// BLOB storage belongs to Go after SQLite finalizes the statement.
	_ = query(t, db, "SELECT randomblob(65536)")
	if !reflect.DeepEqual(got[1], []byte{1, 2}) {
		t.Fatal("BLOB changed after a later step")
	}
	if rows := query(t, db, "SELECT * FROM items WHERE 0"); len(rows.Values) != 0 || len(rows.Columns) != 3 {
		t.Fatal(rows)
	}
	if r := query(t, db, "INSERT INTO items(name) VALUES ('returning') RETURNING id"); r.Values[0][0] != int64(2) {
		t.Fatal(r)
	}
	if r := query(t, db, "SELECT ?, ?, ?", json.Number("42"), json.Number("0.25"), uint32(7)); !reflect.DeepEqual(r.Values[0], []any{int64(42), 0.25, int64(7)}) {
		t.Fatal(r)
	}
}

func TestSQLiteFeatures(t *testing.T) {
	db := testDB(t, ":memory:")
	if v := query(t, db, "SELECT sqlite_version()").Values[0][0]; v != "3.53.4" {
		t.Fatalf("SQLite = %v", v)
	}
	execute(t, db, "CREATE TABLE parent (id PRIMARY KEY)")
	execute(t, db, "CREATE TABLE child (parent REFERENCES parent(id))")
	_, err := db.Execute(context.Background(), "INSERT INTO child VALUES (1)")
	var sqliteErr *Error
	if !errors.As(err, &sqliteErr) || sqliteErr.Code != 19 || sqliteErr.ExtendedCode != 787 {
		t.Fatalf("foreign key: %v", err)
	}
	execute(t, db, "CREATE VIRTUAL TABLE search USING fts5(body)")
	execute(t, db, "INSERT INTO search VALUES ('hello sqlite')")
	if n := query(t, db, "SELECT count(*) FROM search WHERE search MATCH 'sqlite'").Values[0][0]; n != int64(1) {
		t.Fatal(n)
	}
	execute(t, db, "CREATE VIRTUAL TABLE spatial USING rtree(id, x0, x1, y0, y1)")
	if v := query(t, db, `SELECT json_extract('{"a":42}', '$.a')`).Values[0][0]; v != int64(42) {
		t.Fatal(v)
	}
	execute(t, db, "VACUUM")
}

func TestValidationBeforeExecution(t *testing.T) {
	db := testDB(t, ":memory:")
	execute(t, db, "CREATE TABLE items (n UNIQUE)")
	for _, sql := range []string{"INSERT INTO items VALUES (1); INSERT INTO items VALUES (2)", "INSERT INTO items VALUES (3); invalid sql", "INSERT INTO items VALUES (4)\x00;", "", "-- only a comment", "BEGIN", "SAVEPOINT foo", "ATTACH ':memory:' AS other", "VACUUM INTO 'outside.db'"} {
		if _, err := db.Execute(context.Background(), sql); err == nil {
			t.Errorf("accepted %q", sql)
		}
	}
	if n := query(t, db, "SELECT count(*) FROM items").Values[0][0]; n != int64(0) {
		t.Fatalf("partial SQL ran: %v", n)
	}
	execute(t, db, "INSERT INTO items VALUES (?) ; -- trailing comment\n /* another */", 1)
	for _, args := range [][]any{nil, {1, 2}, {math.NaN()}, {math.Inf(1)}, {uint64(math.MaxUint64)}, {json.Number("9223372036854775808")}, {struct{}{}}, {"\xff"}} {
		if _, err := db.Execute(context.Background(), "INSERT INTO items VALUES (?)", args...); err == nil {
			t.Errorf("accepted args %#v", args)
		}
	}
}

func TestTransactions(t *testing.T) {
	db := testDB(t, ":memory:")
	execute(t, db, "CREATE TABLE items (n UNIQUE)")
	results, err := db.Transaction(context.Background(), []Statement{{"INSERT INTO items VALUES (?)", []any{1}}, {"INSERT INTO items VALUES (?)", []any{2}}})
	if err != nil || len(results) != 2 || results[0].Changes != 1 || results[1].Changes != 1 {
		t.Fatalf("%v, %v", results, err)
	}
	for _, second := range []string{"INSERT INTO items VALUES (2)", "COMMIT", "SAVEPOINT escape", "not sql"} {
		results, err := db.Transaction(context.Background(), []Statement{{SQL: "INSERT INTO items VALUES (3)"}, {SQL: second}})
		if err == nil || results != nil {
			t.Fatalf("batch succeeded: %q: %v %v", second, results, err)
		}
		if n := query(t, db, "SELECT count(*) FROM items").Values[0][0]; n != int64(2) {
			t.Fatalf("batch did not roll back: %q: %v", second, n)
		}
	}
	if r, err := db.Transaction(context.Background(), nil); err != nil || r == nil || len(r) != 0 {
		t.Fatalf("empty batch: %v %v", r, err)
	}
}

const longQuery = "WITH RECURSIVE n(x) AS (VALUES(1) UNION ALL SELECT x+1 FROM n WHERE x<1000000000) SELECT sum(x) FROM n"

func TestCancellationAndRollback(t *testing.T) {
	db := testDB(t, ":memory:")
	ctx, cancel := context.WithTimeout(context.Background(), 20*time.Millisecond)
	defer cancel()
	if _, err := db.Query(ctx, longQuery); !errors.Is(err, context.DeadlineExceeded) {
		t.Fatalf("cancellation: %v", err)
	}
	if n := query(t, db, "SELECT 42").Values[0][0]; n != int64(42) {
		t.Fatal(n)
	}
	execute(t, db, "CREATE TABLE items (n)")
	ctx, cancel = context.WithTimeout(context.Background(), 20*time.Millisecond)
	defer cancel()
	if _, err := db.Transaction(ctx, []Statement{{SQL: "INSERT INTO items VALUES (1)"}, {SQL: longQuery}}); !errors.Is(err, context.DeadlineExceeded) {
		t.Fatalf("batch cancellation: %v", err)
	}
	if n := query(t, db, "SELECT count(*) FROM items").Values[0][0]; n != int64(0) {
		t.Fatal("canceled batch did not roll back", n)
	}
}

func TestConcurrentOperations(t *testing.T) {
	db := testDB(t, ":memory:")
	execute(t, db, "CREATE TABLE counter(n)")
	execute(t, db, "INSERT INTO counter VALUES (0)")
	var wg sync.WaitGroup
	for range 16 {
		wg.Go(func() {
			for range 8 {
				if _, err := db.Execute(context.Background(), "UPDATE counter SET n=n+1"); err != nil {
					t.Error(err)
					return
				}
			}
		})
	}
	wg.Wait()
	if n := query(t, db, "SELECT n FROM counter").Values[0][0]; n != int64(128) {
		t.Fatal(n)
	}
}

func TestCloseAndQueuedCancellation(t *testing.T) {
	db := testDB(t, ":memory:")
	started := make(chan struct{})
	done := make(chan error, 1)
	go func() {
		done <- db.operation(context.Background(), func() error { close(started); _, _, err := db.run(longQuery, nil, true); return err })
	}()
	<-started
	ctx, cancel := context.WithTimeout(context.Background(), 20*time.Millisecond)
	defer cancel()
	if _, err := db.Query(ctx, "SELECT 1"); !errors.Is(err, context.DeadlineExceeded) {
		t.Fatalf("queued cancellation: %v", err)
	}
	if err := db.Close(); err != nil {
		t.Fatal(err)
	}
	select {
	case err := <-done:
		if !errors.Is(err, ErrClosed) {
			t.Fatal(err)
		}
	case <-time.After(wait.Guard):
		t.Fatal("close did not interrupt query")
	}
	if _, err := db.Query(context.Background(), "SELECT 1"); !errors.Is(err, ErrClosed) {
		t.Fatal(err)
	}
	if err := db.Close(); err != nil {
		t.Fatal(err)
	}
}

func TestDiskReadOnlyAndBusy(t *testing.T) {
	path := filepath.Join(t.TempDir(), "disk.db")
	w := testDB(t, path)
	execute(t, w, "CREATE TABLE items(n)")
	execute(t, w, "INSERT INTO items VALUES (42)")
	r, err := Open(context.Background(), path, OpenOptions{ReadOnly: true})
	if err != nil {
		t.Fatal(err)
	}
	defer r.Close()
	if n := query(t, r, "SELECT n FROM items").Values[0][0]; n != int64(42) {
		t.Fatal(n)
	}
	if _, err := r.Execute(context.Background(), "DELETE FROM items"); err == nil {
		t.Fatal("read-only write succeeded")
	}
	b, err := Open(context.Background(), path, OpenOptions{BusyTimeout: 30 * time.Millisecond})
	if err != nil {
		t.Fatal(err)
	}
	defer b.Close()
	locked, release, done := make(chan struct{}), make(chan struct{}), make(chan error, 1)
	go func() {
		done <- w.operation(context.Background(), func() error {
			if err := w.control("BEGIN IMMEDIATE"); err != nil {
				close(locked)
				return err
			}
			close(locked)
			<-release
			return w.control("COMMIT")
		})
	}()
	<-locked
	defer func() {
		close(release)
		if err := <-done; err != nil {
			t.Error(err)
		}
	}()
	_, err = b.Execute(context.Background(), "INSERT INTO items VALUES (1)")
	var sqliteErr *Error
	if !errors.As(err, &sqliteErr) || sqliteErr.Code != 5 {
		t.Fatalf("busy: %v", err)
	}
	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Millisecond)
	defer cancel()
	if _, err := b.Execute(ctx, "INSERT INTO items VALUES (1)"); !errors.Is(err, context.DeadlineExceeded) {
		t.Fatalf("busy cancellation: %v", err)
	}
}
